INSERT INTO places(public_id,slug,name_bn,name_en,short_name,category_id,subcategory_id,ownership,division_id,district_id,upazila_id,city_corporation_id,address_en,postcode,lat,lon,website,established,attributes,verification_status,data_source_id,source_notes,last_verified_at,evidence_level,evidence_source_id,production_eligible) VALUES ('INST-00000001','university-of-rajshahi','রাজশাহী বিশ্ববিদ্যালয়','University of Rajshahi','RU',1,5,'public',10002,20015,NULL,50005,'Motihar, Rajshahi 6205','6205',24.37,88.637,'https://www.ru.ac.bd','1953-07-06','{"faculties": 12, "departments": 59, "institutes": 6, "residential_halls": 18, "students": "25,000+", "academic_staff": "1,200+", "campus_acres": 753, "vice_chancellor": "Faridul Islam (since 16 Mar 2026)"}'::jsonb,'verified',11,'Mockups show 56/58 departments, ~34,000–38,000 students and a different VC — all outdated. Inside Rajshahi City Corporation (Motihar thana).','2026-11-09','secondary',11,true);
INSERT INTO places(public_id,slug,name_bn,name_en,short_name,category_id,subcategory_id,ownership,division_id,district_id,upazila_id,city_corporation_id,address_en,postcode,lat,lon,website,established,attributes,verification_status,data_source_id,source_notes,last_verified_at,evidence_level,evidence_source_id,production_eligible) VALUES ('INST-00000002','ruet','রাজশাহী প্রকৌশল ও প্রযুক্তি বিশ্ববিদ্যালয়','Rajshahi University of Engineering & Technology','RUET',1,5,'public',10002,20015,NULL,50005,'Rajshahi–Dhaka Highway, Kazla, Rajshahi 6204','6204',24.3635,88.628,'https://www.ruet.ac.bd','1964','{"university_status_year": 2003, "departments": 14, "faculties": 4, "students": 6484, "academic_staff": 400, "vice_chancellor": "S M Abdur Razzak"}'::jsonb,'verified',12,'Founded as Rajshahi Engineering College (1964), university since Sept 2003. Phone numbers in mockups not verified.','2026-11-09','secondary',12,true);
